        #090b12;
    }

    main {
      width: min(100%, 520px);
    }

    .card {
      padding: 34px;
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 28px;
      background: linear-gradient(145deg, rgba(24, 28, 42, 0.94), rgba(13, 16, 27, 0.96));
      box-shadow: 0 24px 70px rgba(0, 0, 0, 0.42);
      backdrop-filter: blur(18px);
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.75rem, 5vw, 2.35rem);
      letter-spacing: -0.04em;
    }

    .intro {
      margin: 0 0 30px;
