<body>
  <main>
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification Preferences</h1>
      <p class="intro">Choose the channel that works best for your updates.</p>

      <form id="notification-form">
        <div class="form-field">
          <p class="question">How do you prefer to receive notifications?</p>

          <label class="option">
            <input type="radio" name="notification-preference" value="Email" required>
            <span>Email</span>
          </label>

          <label class="option">
            <input type="radio" name="notification-preference" value="SMS">
            <span>SMS</span>
          </label>

          <label class="option">
            <input type="radio" name="notification-preference" value="Push Notifications">
